import { useCallback } from 'react';
import { useSessionStore } from '../stores/sessionStore';
import { createWebPlatform } from '../platform';
import { StartLearningSession } from '../application/use-cases/StartLearningSession';

const platform = createWebPlatform();
const startLearningSession = new StartLearningSession(
  platform.sessionRepo,
  platform.contentRepo
);

/**
 * 学习会话 Hook
 */
export function useLearningSession() {
  const {
    session,
    currentStep,
    steps,
    isLoading,
    error,
    showComplete,
    startSession,
    completeStep,
    requestHint,
    pauseSession,
    resumeSession,
    abandonSession,
    reset,
    setLoading,
    setError,
  } = useSessionStore();

  /**
   * 开始学习
   */
  const start = useCallback(async (knowledgePointId: string) => {
    setLoading(true);
    setError(null);
    try {
      const newSession = await startLearningSession.execute('default-user', knowledgePointId);
      const stepList = await platform.contentRepo.findSteps(knowledgePointId);
      startSession(newSession, stepList);
    } catch (err) {
      setError(err instanceof Error ? err.message : '启动学习失败');
    } finally {
      setLoading(false);
    }
  }, [startSession, setLoading, setError]);

  /**
   * 完成当前步骤
   */
  const complete = useCallback((data: Record<string, unknown> = {}) => {
    completeStep(data);
  }, [completeStep]);

  /**
   * 获取进度百分比
   */
  const getProgress = useCallback(() => {
    if (!session || steps.length === 0) return 0;
    return Math.round((session.currentStepIndex / steps.length) * 100);
  }, [session, steps]);

  return {
    session,
    currentStep,
    steps,
    isLoading,
    error,
    showComplete,
    start,
    complete,
    requestHint,
    pauseSession,
    resumeSession,
    abandonSession,
    reset,
    getProgress,
  };
}
