import React, { useState, useCallback, useMemo } from 'react';
import './SplitCircle.css';

interface CircleConfig {
  /** 分母（分割份数） */
  denominator: number;
  /** 高亮的份数索引数组 */
  highlighted: number[];
  /** 标签 */
  label?: string;
}

interface SplitCircleProps {
  /** 圆配置数组 */
  circles: CircleConfig[];
  /** 完成回调 */
  onComplete?: () => void;
  /** 是否只读模式 */
  readOnly?: boolean;
  /** 圆的大小 */
  size?: number;
}

/**
 * 分割圆可视化组件
 * 用于显示分数的具象表示
 */
export const SplitCircle: React.FC<SplitCircleProps> = ({
  circles,
  onComplete,
  readOnly = false,
  size = 120,
}) => {
  const [localHighlighted, setLocalHighlighted] = useState<CircleConfig[]>(
    circles.map((c) => ({
      denominator: c.denominator,
      highlighted: [...c.highlighted],
      label: c.label
    }))
  );

  const handleSegmentClick = useCallback(
    (circleIndex: number, segmentIndex: number) => {
      if (readOnly) return;
      if (circleIndex >= localHighlighted.length) return;

      const circle = localHighlighted[circleIndex];
      if (!circle) return;

      const isHighlighted = circle.highlighted.includes(segmentIndex);

      const newHighlighted = isHighlighted
        ? circle.highlighted.filter((i) => i !== segmentIndex)
        : [...circle.highlighted, segmentIndex];

      const newCircles = [...localHighlighted];
      newCircles[circleIndex] = {
        ...circle,
        highlighted: newHighlighted.sort((a, b) => a - b),
      };
      setLocalHighlighted(newCircles);

      // 检查是否所有预期的高亮都完成了
      const originalCircle = circles[circleIndex];
      if (!originalCircle) return;

      const isComplete =
        newHighlighted.length >= originalCircle.highlighted.length &&
        originalCircle.highlighted.every((i) => newHighlighted.includes(i));

      if (isComplete && onComplete) {
        onComplete();
      }
    },
    [readOnly, localHighlighted, circles, onComplete]
  );

  return (
    <div className="split-circles">
      {localHighlighted.map((config, circleIndex) => (
        <CircleItem
          key={circleIndex}
          config={config}
          circleIndex={circleIndex}
          size={size}
          readOnly={readOnly}
          onSegmentClick={handleSegmentClick}
        />
      ))}
    </div>
  );
};

/**
 * 单个圆组件
 */
interface CircleItemProps {
  config: CircleConfig;
  circleIndex: number;
  size: number;
  readOnly: boolean;
  onSegmentClick: (circleIndex: number, segmentIndex: number) => void;
}

const CircleItem: React.FC<CircleItemProps> = ({
  config,
  circleIndex,
  size,
  readOnly,
  onSegmentClick,
}) => {
  const { denominator, highlighted, label } = config;

  // 预计算所有扇形角度
  const segments = useMemo(() => {
    const result = [];
    for (let i = 0; i < denominator; i++) {
      const startAngle = (360 / denominator) * i - 90;
      result.push({
        index: i,
        startAngle,
        endAngle: startAngle + 360 / denominator,
      });
    }
    return result;
  }, [denominator]);

  return (
    <div className="split-circle-container">
      {label && <div className="circle-label">{label}</div>}
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="split-circle-svg"
      >
        {/* 背景圆 */}
        <circle
          cx={size / 2}
          cy={size / 2}
          r={size / 2 - 4}
          fill="#f3f4f6"
          stroke="#d1d5db"
          strokeWidth="2"
        />
        {/* 分割线和扇形 */}
        {segments.map((seg) => {
          const isHighlighted = highlighted.includes(seg.index);
          const path = createArcPath(
            size / 2,
            size / 2,
            size / 2 - 4,
            seg.startAngle,
            seg.endAngle - seg.startAngle
          );

          return (
            <g key={`segment-${seg.index}`}>
              {/* 分割线 */}
              <line
                x1={size / 2}
                y1={size / 2}
                x2={size / 2 + (size / 2 - 4) * Math.cos((seg.startAngle * Math.PI) / 180)}
                y2={size / 2 + (size / 2 - 4) * Math.sin((seg.startAngle * Math.PI) / 180)}
                stroke="#9ca3af"
                strokeWidth="1"
              />
              {/* 高亮扇形 */}
              {isHighlighted && (
                <path
                  d={path}
                  fill="#3b82f6"
                  className={`segment ${!readOnly ? 'segment-interactive' : ''}`}
                  onClick={() => onSegmentClick(circleIndex, seg.index)}
                  style={{ cursor: readOnly ? 'default' : 'pointer' }}
                />
              )}
            </g>
          );
        })}
        {/* 中心点 */}
        <circle cx={size / 2} cy={size / 2} r="4" fill="#6b7280" />
      </svg>
      <div className="fraction-label">
        {highlighted.length}/{denominator}
      </div>
    </div>
  );
};

/**
 * 创建扇形路径
 */
function createArcPath(
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  sweepAngle: number
): string {
  const startRad = (startAngle * Math.PI) / 180;
  const endRad = ((startAngle + sweepAngle) * Math.PI) / 180;

  const x1 = cx + r * Math.cos(startRad);
  const y1 = cy + r * Math.sin(startRad);
  const x2 = cx + r * Math.cos(endRad);
  const y2 = cy + r * Math.sin(endRad);

  const largeArc = sweepAngle > 180 ? 1 : 0;

  return [
    `M ${cx} ${cy}`,
    `L ${x1} ${y1}`,
    `A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2}`,
    'Z',
  ].join(' ');
}

export default SplitCircle;
